NI  = {2015:187.8,2016:126.8,2017:233.0,2018:365.4,2019:507.4,2020:369.8,2021:500.2,2022:705.0,2023:969.0,2024:815.0,2025:1350.0}
EQ  = {2014:2270.1,2015:2745.4,2016:4365.8,2017:6849.8,2018:7219.3,2019:8840.6,2020:10634.0,2021:10882.1,2022:11506.0,2023:12489.0,2024:13528.0,2025:14156.0}
OI  = {2015:567.3,2016:618.7,2017:809.0,2018:977.4,2019:1169.6,2020:1052.9,2021:1108.2,2022:1200.0,2023:1443.0,2024:1328.0,2025:1848.0}
NPPE= {2014:4998.3,2015:5606.4,2016:7199.2,2017:9394.6,2018:11026.0,2019:12152.6,2020:14503.1,2021:15445.8,2022:16649.5,2023:18601.0,2024:19249.0,2025:23584.0}
GPPE= {2014:7388.6,2015:8395.6,2016:10650.9,2017:13738.8,2018:15996.6,2019:18087.2,2020:21679.4,2021:23702.9,2022:25982.5,2023:29202.0,2024:30723.0,2025:36972.0}
GW  = {2014:1002.1,2015:1063.2,2016:2986.1,2017:4411.8,2018:4836.4,2019:4781.9,2020:5472.6,2021:5372.0,2022:5654.0,2023:5737.0,2024:5504.0,2025:5984.0}
DA  = {2015:525.5,2016:837.2,2017:1042.5,2018:1227.5,2019:1284.9,2020:1423.3,2021:1656.3,2022:1736.3,2023:1844.0,2024:2011.0,2025:2066.0}
avg = lambda d,y: (d[y]+d[y-1])/2
print("year ROE  OI/avg(netPPE)  (OI+DA)/avg(grossPPE)  ROE-ex-goodwill(NI/(avgEQ-avgGW))")
for y in range(2015,2026):
    print(y, "%.1f%%" % (100*NI[y]/avg(EQ,y)), "%.1f%%" % (100*OI[y]/avg(NPPE,y)), "%.1f%%" % (100*(OI[y]+DA[y])/avg(GPPE,y)), "%.1f%%" % (100*NI[y]/(avg(EQ,y)-avg(GW,y))))
m = lambda f, ys: sum(f(y) for y in ys)/len(ys)
for nm, ys in [("5y 2021-25", range(2021,2026)), ("10y 2016-25", range(2016,2026))]:
    print(nm, "ROE %.1f%%" % (100*m(lambda y: NI[y]/avg(EQ,y), ys)), "ROTE-ish %.1f%%" % (100*m(lambda y: NI[y]/(avg(EQ,y)-avg(GW,y)), ys)), "OI/netPPE %.1f%%" % (100*m(lambda y: OI[y]/avg(NPPE,y), ys)))
